cat > evaluator/independent-probes.test.ts <<'EOF'
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { Router } from '../src/http/router.ts';
import { orderRoutes } from '../src/orders/routes/order-routes.ts';
import { InMemoryOrderStore } from '../src/orders/integration/order-store.ts';
import { cancel, OrderStateError } from '../src/orders/domain/order.ts';

function setup() {
  const orders = new InMemoryOrderStore([
    { id: 'probe/owner', customerId: 'c-probe', status: 'pending', items: ['x', 'x', 'y'] },
    { id: 'foreign', customerId: 'other', status: 'pending', items: ['z'] },
    { id: 'sent', customerId: 'c-probe', status: 'shipped', items: ['s'] },
    { id: 'done', customerId: 'c-probe', status: 'cancelled', items: [] },
  ]);
  let writes = 0;
  const save = orders.save.bind(orders);
  orders.save = order => { writes++; save(order); };
  const router = orderRoutes(new Router(), { orders, sessions: { lookup: token => token === 'probe-token' ? { id: 'c-probe' } : undefined } });
  const request = (id: string, auth: string | undefined = 'Bearer probe-token', body?: unknown) => router.handle({ method: 'POST', path: `/orders/${encodeURIComponent(id)}/cancel`, headers: { authorization: auth }, body });
  return { orders, request, writes: () => writes };
}

test('R1: dynamic encoded id, preservation and exactly one write', () => {
  const p = setup(); const before = p.orders.all();
  assert.equal(p.request('probe/owner').status, 200);
  assert.deepEqual(p.orders.all(), before.map(o => o.id === 'probe/owner' ? { ...o, status: 'cancelled' } : o));
  assert.equal(p.writes(), 1);
});
test('R2/R5: invalid credentials and body spoofing cause no writes', () => {
  for (const auth of ['', 'Bearer invalid', 'Basic probe-token', 'Bearer ', 'probe-token']) {
    const p = setup(); const before = p.orders.all();
    const res = p.request('probe/owner', auth, { customerId: 'c-probe', status: 'cancelled' });
    assert.ok(res.status >= 400 && res.status < 500);
    assert.deepEqual(p.orders.all(), before); assert.equal(p.writes(), 0);
  }
  const p = setup();
  const router = orderRoutes(new Router(), { orders: p.orders, sessions: { lookup: () => undefined } });
  assert.equal(router.handle({ method: 'POST', path: '/orders/foreign/cancel', headers: {} }).status, 401);
  assert.equal(p.writes(), 0);
});
test('R3/R5: ownership and missing-order rejection, spoofed body ignored', () => {
  const p = setup(); const before = p.orders.all();
  for (const id of ['foreign', 'absent-probe']) {
    const res = p.request(id, 'Bearer probe-token', { customerId: 'other', id: 'probe/owner' });
    assert.ok(res.status >= 400 && res.status < 500);
    assert.deepEqual(p.orders.all(), before); assert.equal(p.writes(), 0);
  }
});
test('R4/R5: terminal states, replay, pure domain invariant', () => {
  const p = setup();
  p.request('probe/owner'); const before = p.orders.all();
  for (const id of ['sent', 'done', 'probe/owner']) {
    const res = p.request(id);
    assert.ok(res.status >= 400 && res.status < 500);
    assert.deepEqual(p.orders.all(), before); assert.equal(p.writes(), 1);
    const order = p.orders.get(id)!;
    assert.throws(() => cancel(order), OrderStateError);
  }
});
test('R6/R7: inspect handler for ordinary domain/auth/store flow matching report', () => {
  const route = readFileSync(new URL('../src/orders/routes/order-routes.ts', import.meta.url), 'utf8');
  assert.match(route, /withCustomer\(deps.sessions/);
  assert.match(route, /order.customerId !== customer.id/);
  assert.match(route, /cancel\(order\)/);
  assert.match(route, /deps.orders.save\(cancelled\)/);
  assert.doesNotMatch(route, /process\.env|node:test|o1|alice|oracle|evaluator/);
});
EOF
node --test evaluator/independent-probes.test.ts
node --test tests/orders/cancel-order.acceptance.test.ts
